const data = $json.body.data;
const msgObj = data.message || {};
const messageType = Object.keys(msgObj)[0] || 'unknown';

return [{
  json: {
    phone: data.key.remoteJid.replace('@s.whatsapp.net', ''),
    candidate_name: data.pushName || '',
    message_type: messageType,
    timestamp: data.messageTimestamp,
    raw_key: JSON.stringify(data.key),
    raw_message: JSON.stringify(msgObj),
    instance: $json.body.instance
  }
}];

const msg = JSON.parse($json.raw_message);
const text = msg.conversation || msg.extendedTextMessage?.text || '';

return [{
  json: {
    ...$json,
    extracted_content: text,
    content_type: 'text',
    binary_data: null
  }
}];

const base64 = $json.base64;
const meta = $('🧹 Normalizar Payload').first().json;
const msg = JSON.parse(meta.raw_message);

const mime = msg.audioMessage?.mimetype || 'audio/ogg; codecs=opus';
const mimeClean = mime.split(';')[0].trim();

const extMap = {
  'audio/ogg': 'ogg',
  'audio/mpeg': 'mp3',
  'audio/mp4': 'mp4',
  'audio/wav': 'wav',
  'audio/x-wav': 'wav',
  'audio/m4a': 'm4a',
  'audio/webm': 'webm'
};
const ext = extMap[mimeClean] || 'ogg';

const buffer = Buffer.from(base64, 'base64');

return [{
  json: { ...meta, audio_mime: mimeClean, audio_ext: ext },
  binary: {
    data: {
      data: buffer,
      mimeType: mimeClean,
      fileName: `audio.${ext}`
    }
  }
}];

const transcription = $input.first().json;
const meta = $('🧹 Normalizar Payload').first().json;

return [{
  json: {
    ...meta,
    extracted_content: transcription.text || '',
    content_type: 'audio'
  }
}];

const imageResult = $input.first().json;
const meta = $('🧹 Normalizar Payload').first().json;

const extractedText = imageResult.content
  || imageResult.text
  || imageResult.choices?.[0]?.message?.content
  || JSON.stringify(imageResult);

return [{
  json: {
    ...meta,
    extracted_content: extractedText,
    content_type: 'image'
  }
}];

const base64 = $json.base64;
const meta = $('🧹 Normalizar Payload').first().json;
const msg = JSON.parse(meta.raw_message);

const mime = msg.documentMessage?.mimetype || 'application/octet-stream';
const fileName = msg.documentMessage?.fileName || 'documento';

const mimeToOp = {
  'application/pdf': 'pdf',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'docx',
  'application/msword': 'docx',
  'text/plain': 'text'
};
const fileOp = mimeToOp[mime] || 'pdf';

const buffer = Buffer.from(base64, 'base64');

return [{
  json: { ...meta, doc_mime: mime, doc_filename: fileName, doc_operation: fileOp },
  binary: {
    data: {
      data: buffer,
      mimeType: mime,
      fileName: fileName
    }
  }
}];

const docData = $input.first().json;
const docMeta = $('🔄 Converter Documento para Binário').first().json;
const meta = $('🧹 Normalizar Payload').first().json;

return [{
  json: {
    ...meta,
    extracted_content: docData.text || docData.data || '',
    content_type: 'document',
    file_type: docMeta.doc_mime || 'application/pdf',
    file_name: docMeta.doc_filename || 'documento'
  }
}];

const sessao = Array.isArray($json) ? $json[0] : $json;
const historico = sessao.historico_conversa || [];

const mergeNode = $('🔗 Unificar Conteúdo').item.json;
const contentType = mergeNode.content_type;
const extractedContent = mergeNode.extracted_content;
const binaryData = mergeNode.binary_data;
const phone = mergeNode.phone;
const candidateName = mergeNode.candidate_name;

const systemMsg = {
  role: 'system',
  content: 'Es um assistente de triagem de candidatos chamado Luisa, simpatica e profissional. Trabalhas para uma empresa angolana e conduzes entrevistas de triagem pelo WhatsApp.\n\nO teu objectivo e recolher obrigatoriamente estes dados:\n1. Nome completo\n2. Experiencia profissional (anos e area)\n3. Disponibilidade (imediata, 15 dias, 30 dias, outra)\n4. Expectativa salarial mensal em AOA\n5. Nivel de escolaridade\n6. Localizacao (bairro e municipio)\n\nREGRAS:\n- Faz sempre UMA pergunta de cada vez, de forma natural\n- Adapta a linguagem ao registo do candidato\n- Se receberes um CV em documento ou imagem, extrai as informacoes disponiveis e confirma com o candidato em vez de perguntar de novo\n- Se receberes audio, usa a transcricao para continuar a conversa naturalmente\n- Quando tiveres todos os dados obrigatorios confirmados, usa a tool qualificar_candidato\n- Se o candidato nao responder de forma util apos 3 tentativas, usa encerrar_sessao com motivo sem_resposta\n- Responde sempre em portugues de Angola\n- Nunca prometas emprego - apenas recolhes informacao para a equipa'
};

let novaMsg;
if (contentType === 'text') {
  novaMsg = { role: 'user', content: extractedContent };
} else if (contentType === 'audio') {
  novaMsg = { role: 'user', content: '[Transcricao de voz]: ' + extractedContent };
} else if (contentType === 'image') {
  novaMsg = { role: 'user', content: [
    { type: 'image_url', image_url: { url: 'data:image/jpeg;base64,' + binaryData } },
    { type: 'text', text: 'Candidato enviou esta imagem.' }
  ]};
} else if (contentType === 'document') {
  novaMsg = { role: 'user', content: '[Documento]: ' + extractedContent };
} else {
  novaMsg = { role: 'user', content: 'Mensagem nao suportada.' };
}

const base = historico.length > 0 && historico[0].role === 'system' ? historico : [systemMsg, ...historico];

return [{ json: {
  messages: [...base, novaMsg],
  phone: phone,
  candidate_name: candidateName,
  sessao_id: sessao.id,
  iteracao: 0
}}];

