parameters.jsCode:
const choice = $json.choices[0];
const toolCall = choice.message.tool_calls[0];

if (!toolCall) {
  throw new Error('Nenhum tool_call encontrado na resposta OpenAI.');
}

return [{ json: {
  ...$json,
  assistant_message: choice.message,
  tool_name: toolCall.function.name,
  tool_input: JSON.parse(toolCall.function.arguments),
  tool_call_id: toolCall.id
}}];

let toolOutput;
if ($json.candidato_qualificado) {
  toolOutput = { success: true, message: 'Candidato guardado com sucesso.' };
} else if ($json.status === 'encerrada' || $json.motivo_encerramento) {
  toolOutput = { success: true, message: 'Sessao encerrada.' };
} else {
  const vaga = Array.isArray($json) ? $json[0] : $json;
  toolOutput = vaga || { message: 'Nenhuma vaga activa encontrada.' };
}

const assistantMsg = $json.assistant_message;

const toolResultMsg = {
  role: 'tool',
  tool_call_id: $json.tool_call_id,
  content: JSON.stringify(toolOutput)
};

const updatedMessages = [...($json.messages || []), assistantMsg, toolResultMsg];
const iteracao = ($json.iteracao || 0) + 1;

if (iteracao >= 5) {
  return [{ json: { ...$json, force_stop: true, messages: updatedMessages, iteracao } }];
}

return [{ json: { ...$json, force_stop: false, messages: updatedMessages, iteracao } }];

const textBlock = ($json.content || []).find(b => b.type === 'text');
const agentResponse = textBlock ? textBlock.text :
  'Ocorreu um erro. Por favor tenta novamente.';
return [{ json: { ...$json, agent_response: agentResponse } }];

